"""Minimal pseudo-legal move generator (no castling/en passant/promotion/check legality)."""

FILES = 'abcdefgh'


def _parse(fen):
    parts = fen.split()
    placement = parts[0]
    active = parts[1] if len(parts) > 1 else 'w'
    board = ['.'] * 64  # index = rank*8 + file, rank 0 = rank 1
    rank = 7
    file = 0
    for ch in placement:
        if ch == '/':
            rank -= 1
            file = 0
        elif ch.isdigit():
            file += int(ch)
        else:
            board[rank * 8 + file] = ch
            file += 1
    return board, active


def _square(file, rank):
    return rank * 8 + file


def _in_bounds(sq, file):
    rank = sq // 8
    return 0 <= rank < 8 and 0 <= file < 8 and sq - rank * 8 == file


def _gen(board, active):
    moves = []
    white = active == 'w'
    for sq in range(64):
        piece = board[sq]
        if piece == '.':
            continue
        if white != piece.isupper():
            continue
        file = sq % 8
        rank = sq // 8
        if piece == 'P' or piece == 'p':
            pawn_dir = 8 if white else -8
            start_rank = 1 if white else 6
            fwd = sq + pawn_dir
            if 0 <= fwd < 64 and board[fwd] == '.':
                moves.append((sq, fwd))
                if rank == start_rank:
                    dbl = sq + 2 * pawn_dir
                    if board[dbl] == '.':
                        moves.append((sq, dbl))
                for cap_offset in (pawn_dir - 1, pawn_dir + 1):
                    cap = sq + cap_offset
                    cfile = cap % 8
                    if cap_offset in (7, 9, -7, -9) and 0 <= cap < 64 and abs(cfile - file) == 1:
                        tgt = board[cap]
                        if tgt != '.' and (white != tgt.isupper()):
                            moves.append((sq, cap))
            # also handle captures even if forward blocked
            for cap_offset in (pawn_dir - 1, pawn_dir + 1):
                cap = sq + cap_offset
                cfile = cap % 8
                if 0 <= cap < 64 and abs(cfile - file) == 1:
                    tgt = board[cap]
                    if tgt != '.' and (white != tgt.isupper()):
                        if not (0 <= fwd < 64 and board[fwd] == '.' and (sq, cap) in moves):
                            moves.append((sq, cap))
        elif piece == 'N' or piece == 'n':
            for dr, df in ((2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)):
                r, f = rank + dr, file + df
                if 0 <= r < 8 and 0 <= f < 8:
                    tgt = r * 8 + f
                    opp = board[tgt]
                    if opp == '.' or (white != opp.isupper()):
                        moves.append((sq, tgt))
        elif piece == 'K' or piece == 'k':
            for dr in (-1, 0, 1):
                for df in (-1, 0, 1):
                    if dr == 0 and df == 0:
                        continue
                    r, f = rank + dr, file + df
                    if 0 <= r < 8 and 0 <= f < 8:
                        tgt = r * 8 + f
                        opp = board[tgt]
                        if opp == '.' or (white != opp.isupper()):
                            moves.append((sq, tgt))
        else:
            diagonals = piece in 'BQ' or piece in 'bq'
            straights = piece in 'RQ' or piece in 'rq'
            dirs = []
            if straights:
                dirs += [(1, 0), (-1, 0), (0, 1), (0, -1)]
            if diagonals:
                dirs += [(1, 1), (1, -1), (-1, 1), (-1, -1)]
            for dr, df in dirs:
                r, f = rank + dr, file + df
                while 0 <= r < 8 and 0 <= f < 8:
                    tgt = r * 8 + f
                    opp = board[tgt]
                    if opp == '.':
                        moves.append((sq, tgt))
                    else:
                        if white != opp.isupper():
                            moves.append((sq, tgt))
                        break
                    r += dr
                    f += df
    return moves


def _uci(frm, to):
    return FILES[frm % 8] + str(frm // 8 + 1) + FILES[to % 8] + str(to // 8 + 1)


def _other(active):
    return 'b' if active == 'w' else 'w'


def legal_moves(fen):
    board, active = _parse(fen)
    return [_uci(frm, to) for frm, to in _gen(board, active)]


def perft(fen, depth):
    board, active = _parse(fen)

    def rec(b, a, d):
        if d == 0:
            return 1
        total = 0
        for frm, to in _gen(b, a):
            nb = b[:]
            nb[to] = nb[frm]
            nb[frm] = '.'
            total += rec(nb, _other(a), d - 1)
        return total

    return rec(board, active, depth)

